function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function parseKV(t){
  return splitLines(t).map(function(l){
    var i=l.indexOf(':'), j=l.indexOf('：');
    var pos=-1; if(i>=0&&(j<0||i<j)) pos=i; else if(j>=0) pos=j;
    if(pos<=0) return {k:l.trim(), v:''};
    return {k:l.slice(0,pos).trim(), v:l.slice(pos+1).trim()};
  }).filter(function(x){return x.k;});
}
function buildModelCard(o){
  o=o||{};
  var name=String(o.name||'').trim()||'UnnamedModel';
  var type=String(o.type||'文本生成').trim()||'文本生成';
  var version=String(o.version||'1.0').trim()||'1.0';
  var uses=splitLines(o.uses); if(!uses.length) uses=['（待补充预期用途）'];
  var limits=splitLines(o.limits); if(!limits.length) limits=['（待补充已知局限）'];
  var metrics=parseKV(o.metrics);
  var ethics=splitLines(o.ethics); if(!ethics.length) ethics=['数据来源需合规，避免包含个人隐私','输出需标注为模型生成，防止误导'];
  var outof=splitLines(o.outofscope).join('；')||'（待补充）';
  var lines=[];
  lines.push('# 模型卡片：'+name+' v'+version);
  lines.push('');
  lines.push('## 一、概述');
  lines.push('- 模型类型：'+type);
  lines.push('- 版本：'+version);
  lines.push('- 一句话描述：'+String(o.summary||'').trim()||'（待补充）');
  lines.push('');
  lines.push('## 二、预期用途');
  lines.push('- 适用场景：'); uses.forEach(function(u){ lines.push('  - '+u); });
  lines.push('- 不适用场景：'+outof);
  lines.push('');
  lines.push('## 三、关键指标');
  if(metrics.length){ lines.push('| 指标 | 数值 |'); lines.push('| --- | --- |'); metrics.forEach(function(m){ lines.push('| '+m.k+' | '+m.v.replace(/\|/g,'/')+' |'); }); }
  else { lines.push('（暂无指标，建议补充准确率 / 延迟 / 困惑度等）'); }
  lines.push('');
  lines.push('## 四、伦理与安全');
  ethics.forEach(function(e){ lines.push('- '+e); });
  lines.push('');
  lines.push('## 五、已知局限');
  limits.forEach(function(l){ lines.push('- '+l); });
  lines.push('');
  lines.push('## 六、许可证');
  lines.push('- '+(String(o.license||'').trim()||'（待补充许可证，如 MIT / Apache-2.0）'));
  return {title:name+' 模型卡片', metricCount:metrics.length, useCount:uses.length, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, parseKV:parseKV, buildModelCard:buildModelCard};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ModelCardForgePure = EXPORTS; }
